script:
$ErrorActionPreference = "Stop"
if ($ExecutionContext.SessionState.LanguageMode -eq 'FullLanguage') { $OutputEncoding = [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false) }
Import-Module -Name $env:XINGMANG_UPDATE_SECURITY_MODULE -Force -ErrorAction Stop
Import-Module -Name $env:XINGMANG_UPDATE_UTILITY_MODULE -Force -ErrorAction Stop
$signature = Microsoft.PowerShell.Security\Get-AuthenticodeSignature -LiteralPath $env:XINGMANG_UPDATE_SIGNATURE_TARGET -ErrorAction Stop
if ($null -eq $signature) { throw "Get-AuthenticodeSignature did not return a result" }
if ($null -eq $signature.SignerCertificate) { throw "The update installer has no signer certificate" }
$xingmangJson = @{
  Status = [string]$signature.Status
  Path = [string]$signature.Path
  Subject = [string]$signature.SignerCertificate.Subject
} | Microsoft.PowerShell.Utility\ConvertTo-Json -Compress
if ($ExecutionContext.SessionState.LanguageMode -ne 'FullLanguage' -and $xingmangJson -match '[^\x00-\x7F]') { $xingmangJson = -join @(foreach ($xingmangChar in $xingmangJson.ToCharArray()) { if ([int]$xingmangChar -gt 127) { '\u{0:x4}' -f [int]$xingmangChar } else { [string]$xingmangChar } }) }
$xingmangJson

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
if ($ExecutionContext.SessionState.LanguageMode -eq 'FullLanguage') { $OutputEncoding = [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false) }
Import-Module -Name 'Microsoft.PowerShell.Utility', 'Appx' -ErrorAction SilentlyContinue
$packages = @(Get-AppxPackage -Name 'Microsoft.DesktopAppInstaller' -ErrorAction Stop | Sort-Object Version -Descending)
if ($packages.Count -eq 0) {
  try {
    $packages = @(Get-AppxPackage -AllUsers -Name 'Microsoft.DesktopAppInstaller' -ErrorAction Stop | Sort-Object Version -Descending)
  } catch {
    $packages = @()
  }
}
if ($packages.Count -gt 0) {
  $package = $packages[0]
  $xingmangJson = @{
    name = [string]$package.Name
    packageFamilyName = [string]$package.PackageFamilyName
    installLocation = [string]$package.InstallLocation
  } | ConvertTo-Json -Compress
  if ($ExecutionContext.SessionState.LanguageMode -ne 'FullLanguage' -and $xingmangJson -match '[^\x00-\x7F]') { $xingmangJson = -join @(foreach ($xingmangChar in $xingmangJson.ToCharArray()) { if ([int]$xingmangChar -gt 127) { '\u{0:x4}' -f [int]$xingmangChar } else { [string]$xingmangChar } }) }
  $xingmangJson
}

if ($ExecutionContext.SessionState.LanguageMode -eq 'FullLanguage') { $OutputEncoding = [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false) }
Import-Module -Name 'Microsoft.PowerShell.Utility', 'CimCmdlets' -ErrorAction SilentlyContinue
$ErrorActionPreference = "SilentlyContinue"
$root = [string]$env:XINGMANG_CLI_PROCESS_ROOT
if (-not $root) { '[]'; exit 0 }
$items = @(Get-CimInstance Win32_Process | ForEach-Object {
      $image = [string]$_.ExecutablePath
      $commandLine = [string]$_.CommandLine
      # A node-hosted CLI runs as node.exe with the entry script on its command
      # line, while a native one runs as its own binary. Accept either, but only
      # when the managed package directory itself is what shows up.
      $matched = $false
      if ($image -and $image.StartsWith($root, [System.StringComparison]::OrdinalIgnoreCase)) { $matched = $true }
      if (-not $matched -and $commandLine -and $commandLine.IndexOf($root, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { $matched = $true }
      if ($matched) {
        @{ ProcessId = $_.ProcessId; Name = [string]$_.Name; ExecutablePath = $image }
      }
    })
$xingmangJson = $items | ConvertTo-Json -Compress
if ($ExecutionContext.SessionState.LanguageMode -ne 'FullLanguage' -and $xingmangJson -match '[^\x00-\x7F]') { $xingmangJson = -join @(foreach ($xingmangChar in $xingmangJson.ToCharArray()) { if ([int]$xingmangChar -gt 127) { '\u{0:x4}' -f [int]$xingmangChar } else { [string]$xingmangChar } }) }
$xingmangJson
